// Two complete native exposures share a ground registration. These temporary
// surfaces exist only while the rabbit is summoned; atlas pigments stay intact.
function surface(w,h) {
  const canvas=document.createElement("canvas"); canvas.width=w; canvas.height=h;
  return canvas.getContext("2d",{willReadFrequently:true});
}
function ramp(a,b,n) {
  const u=Math.max(0,Math.min(1,(n-a)/(b-a))); return u*u*(3-2*u);
}
function coverage(row,w) {
  let l=0,r=w-1;
  while(l<w && row[l*4+3]<120)l++;
  while(r>=l && row[r*4+3]<120)r--;
  if(l>r)return null;
  const a=x=>row[4*x+3];
  return [l===0?l:l-(a(l)-120)/(a(l)-a(l-1)||1),
    r===w-1?r:r+(a(r)-120)/(a(r)-a(r+1)||1)];
}
function premultiply(pixels) {
  for(let i=0;i<pixels.length;i+=4) if(pixels[i+3]<255)
    for(let k=0;k<3;k++)pixels[i+k]*=pixels[i+3]/255;
  return pixels;
}
// Signed distance to the painted outer pencil. Moving this boundary at a
// disocclusion keeps an emerging foot solid, including its antialiased edge.
function silhouette(pixels,n) {
  const distance=new Float32Array(n*n),alpha=i=>pixels[4*i+3],inside=i=>alpha(i)>=128;
  distance.fill(24);
  for(let y=1;y<n-1;y++)for(let x=1;x<n-1;x++){
    const i=n*y+x, on=inside(i);
    if (on!==inside(i-1)||on!==inside(i+1)||on!==inside(i-n)||on!==inside(i+n))
      distance[i]=Math.abs(alpha(i)/255-.5);
  }
  for(const sign of [1,-1]){
    for(let j=1;j<n-1;j++)for(let k=1;k<n-1;k++){
      const y=sign===1?j:n-1-j,x=sign===1?k:n-1-k,i=n*y+x;
      distance[i]=Math.min(distance[i],1+distance[i-sign],1+distance[i-n*sign],
        1.414+distance[i-n*sign+1],1.414+distance[i-n*sign-1]);
    }
  }
  for(let i=0;i<distance.length;i++)if(!inside(i))distance[i]*=-1;
  return distance;
}
// Eye centres and muzzle in the common 384px plate. Keep one crisp expression
// while the surrounding fur turns or a sleeping lid opens.
const expressions={
  loaf:[82,249,158,253,108,278], sploot:[50,305,119,312,80,328],
  onFlank:[115,347,105,295,133,320],halfRoll:[109,274,177,241,159,282]
};
// STAND GUIDE START
const riseGuides = {"idle":[6,1.5,["","","","",""]],"standHalf":[6,1.5,["","","","",""]],"loaf":[6,0.5,["","","","",""]],"sploot":[6,0.5,["","","","",""]],"onFlank":[6,0.5,["","","","",""]],"halfRoll":[6,0.5,["","","","",""]]};
const standEdges = ["", ""];
// STAND GUIDE END
function print(c,box,ctx,pixels,probe) {
  const [x,y,w,h]=box;
  if (!probe) { c.drawImage(ctx.canvas,x,y,w,h); return; }
  const pt=new DOMPoint(probe.x,probe.y).matrixTransform(c.getTransform().inverse());
  const ix=Math.floor((pt.x-x)/w*pixels.width),iy=Math.floor((pt.y-y)/h*pixels.height);
  if(ix>=0 && iy>=0 && ix<pixels.width && iy<pixels.height && pixels.data[4*(iy*pixels.width+ix)+3]>64)
    probe.hit=true;
}

export class PeekTorso {
  constructor(rig) {
    this.box=[-96,-171,196,174];
    const [x,y,w,h]=this.box,d=1.6;
    this.ctx=surface(Math.ceil(w*d),Math.ceil(h*d));
    const ctx=this.ctx,W=ctx.canvas.width,H=ctx.canvas.height;
    const sx=W/w,sy=H/h,rear=rig.art.rear;
    const patch=(name,ox,oy)=>{
      const [dx,dy,pw,ph]=rear.boxes[name];rig.part(ctx,name,ox+dx,oy+dy,pw,ph);
    };
    const probe=rig.probe;rig.probe=null;
    try {
      ctx.setTransform(sx,0,0,sy,-x*sx,-y*sy);
      patch("bNape",-92,-rear.height);
      const neck=ctx.getImageData(0,0,W,H);
      patch("bBody",-92,-rear.height);
      this.quiet=premultiply(ctx.getImageData(0,0,W,H).data);
      const turned=ctx.createImageData(W,H);
      // Pin the base of the neck to the shoulder. Only the crown moves with
      // the ears. Fade its hidden right half beneath the opaque cheek painting.
      for(let j=0;j<H;j++){
        const wy=y+(j+.5)/sy, shift=15*(1-ramp(-168,-133,wy))*sx;
        const seam=17+35*ramp(-157,-116,wy);
        for(let i=1;i<W-1;i++){
          const at=i-shift, ix=Math.floor(at);
          if(ix<0)continue;
          const f=at-ix, m=4*(j*W+ix), n=4*(j*W+i);
          const left=(1-f)*neck.data[m+3],right=f*neck.data[m+7],a=left+right;
          if(a<.1)continue;
          for(let k=0;k<3;k++)turned.data[n+k]=(neck.data[m+k]*left+neck.data[m+4+k]*right)/a;
          turned.data[n+3]=a*(1-ramp(seam-4,seam+4,x+(i+.5)/sx));
        }
      }
      ctx.putImageData(turned,0,0);
      patch("bBody",-92,-rear.height);
      patch("bPeek",-44,-167.7);
      this.turned=premultiply(ctx.getImageData(0,0,W,H).data);
      this.frame=ctx.createImageData(W,H);
      this.rows=Array.from({length:H},(_,j)=>{
        const at=j*W*4, a=coverage(this.quiet.subarray(at,at+W*4),W),
          b=coverage(this.turned.subarray(at,at+W*4),W);
        return a||b ? [a||b,b||a] : null;
      });
    } finally {rig.probe=probe;ctx.resetTransform();}
  }
  draw(c,t,probe) {
    if(t!==this.last) {
      const {width:w,height:h,data:out}=this.frame, a=this.quiet,b=this.turned;
      for(let j=0;j<h;j++) {
        const bounds=this.rows[j];if(!bounds)continue;
        const [[al,ar],[bl,br]]=bounds,l=al+(bl-al)*t,r=ar+(br-ar)*t;
        const row=4*j*w;out.fill(0,row,row+4*w);
        for(let x=Math.max(1,Math.floor(l)-2);x<Math.min(w-1,Math.ceil(r)+3);x++){
          const u=(x-l)/Math.max(.01,r-l);
          const ax=Math.max(0,Math.min(w-1.001,al+u*(ar-al))),bx=Math.max(0,Math.min(w-1.001,bl+u*(br-bl)));
          const ai=row+4*(ax|0),bi=row+4*(bx|0),i=row+4*x;
          const an=(1-ax%1)*(1-t),af=(ax%1)*(1-t),bn=(1-bx%1)*t,bf=bx%1*t;
          const alpha=a[ai+3]*an+a[ai+7]*af+b[bi+3]*bn+b[bi+7]*bf;
          if(alpha<.5)continue;
          out[i+3]=alpha;
          for(let k=0;k<3;k++)out[i+k]=(a[ai+k]*an+a[ai+4+k]*af+b[bi+k]*bn+b[bi+4+k]*bf)*255/alpha;
        }
      }
      this.ctx.putImageData(this.frame,0,0); this.last=t;
    }
    print(c,this.box,this.ctx,this.frame,probe);
  }
}

// Isolate the pencil and cream tips of the half-rise painting. While a paw
// leaves the floor the unmarked belly behind it must remain a single coat.
function risingPaws(pixels,n) {
  const paths=[
    {root:[91,251],foot:[118,350],angle:-.20,
      edge:[[69,251],[78,246],[96,242],[110,246],[119,250],[126,259],[132,273],[134,288],
        [131,299],[122,304],[105,305],[96,300],[88,294],[82,285],[79,275],[72,263],[68,256]]},
    {root:[184,254],foot:[168,350],angle:.22,
      edge:[[179,244],[194,243],[208,251],[216,270],[209,280],[199,285],[194,292],
        [183,300],[169,307],[155,308],[146,304],[141,298],[139,286],[143,274],[150,263],[161,253]]}
  ];
  const leftEdge=new Int16Array(n);
  for(let y=0;y<n;y++){let x=0;while(x<n&&pixels[4*(y*n+x)+3]<175)x++;leftEdge[y]=x;}
  return paths.map(({root,foot,angle,edge})=>{
    const x=Math.min(...edge.map(p=>p[0]))-2,y=Math.min(...edge.map(p=>p[1]))-2;
    const w=Math.max(...edge.map(p=>p[0]))-x+3,h=Math.max(...edge.map(p=>p[1]))-y+3;
    const c=surface(w,h);
    c.beginPath();edge.forEach(([u,v],i)=>i?c.lineTo(u-x,v-y):c.moveTo(u-x,v-y));c.closePath();c.fill();
    const cut=c.getImageData(0,0,w,h),alpha=cut.data;
    for(let j=0;j<h;j++)for(let i=0;i<w;i++){
      const col=x+i,row=y+j,src=4*(row*n+col),dst=4*(j*w+i);
      const fade=ramp(0,7,row-y-1)*ramp(.7,3.6,col-leftEdge[row]);
      const cover=alpha[dst+3]/255*fade;
      if(!cover){alpha[dst+3]=0;continue;}
      // Sample the very same chest wash below this lifted arm, above the heels.
      const donor=4*((317+(j*.37|0))*n+Math.max(91,col));
      for(let k=0;k<3;k++){
        alpha[dst+k]=pixels[src+k];
        pixels[src+k]+=(pixels[donor+k]-pixels[src+k])*cover;
      }
      alpha[dst+3]=255*cover;
    }
    c.putImageData(cut,0,0);
    return {canvas:c.canvas,x,y,root,foot,angle};
  });
}

// At the right cheek the seated head is in front of a shoulder. Standing up
// uncovers the head silhouette. Register those two boundaries separately so
// the shoulder stroke can disappear behind the cheek without cutting across it.
function cheekRows(rig,face,p,box,n,a,b) {
  const c=surface(n,n),[left,top,w,h]=box;
  c.scale(n/w,n/h);c.translate(-left,-top);
  const probe=rig.probe;rig.probe=null;
  try{rig.front(c,{...p,action:"idle",breath:0,sniff:0,ear:0,blink:0,tilt:0},false);}
  finally{rig.probe=probe;}
  const head=c.getImageData(0,0,n,n).data;
  c.save();c.resetTransform();c.clearRect(0,0,n,n);c.restore();
  rig.probe=null;
  try{rig.part(c,"fBody",...rig.art.front.fBody);}finally{rig.probe=probe;}
  const torso=premultiply(c.getImageData(0,0,n,n).data);
  const ay=[145,165,181,197,214,230,246,258,267,275,281,294,307,328];
  const by=[115,130,142,152,161,172,187,199,209,218,225,243,263,298];
  // The standing shoulder continues behind the broad cheek. Its hidden edge
  // is not the outer edge of that cheek.
  const shoulder=[204,213,218,224,229,235,242,248,254,260,264,277,291,312];
  const lowerCheek=[272,271,270,269,268,266,265,263,262,261,259,256,253,249,246,242,237,232,226,218,211,207];
  const right=(im,row)=>coverage(im.subarray(row*n*4,(row+1)*n*4),n)?.[1]??0;
  const rows=ay.slice(1).flatMap((to,i)=>Array.from({length:to-ay[i]},(_,j)=>{
    const y=ay[i]+j, v=by[i]+j/(to-ay[i])*(by[i+1]-by[i]);
    const yr=Math.round(v),outer=right(b,yr);
    const cheek=v<211?outer:v>=232?207+(v-232)*.6:
      lowerCheek[Math.floor(v)-211]+(v%1)*(lowerCheek[Math.ceil(v)-211]-lowerCheek[Math.floor(v)-211]);
    const la=y<282?right(head,y):Math.max(213,right(head,y),213+(y-282)*.40);
    const guided=shoulder[i]+j/(to-ay[i])*(shoulder[i+1]-shoulder[i]);
    const bodyB=guided+(outer-guided)*ramp(220,234,v);
    return [y,v,la,cheek,Math.max(190,right(torso,y)),bodyB];
  }));
  return {rows,torso};
}

function resolveCheek({rows,torso},a,b,out,n,t) {
  const mix=(x,y,u)=>x+(y-x)*u;
  const sample=(im,x,y,k)=>{
    const i=4*((y|0)*n+(x|0)),s=x%1,v=y%1;
    return mix(mix(im[i+k],im[i+4+k],s),mix(im[i+n*4+k],im[i+n*4+4+k],s),v);
  };
  for(let j=1;j<rows.length;j++){
    const before=rows[j-1],after=rows[j],y0=mix(before[0],before[1],t),y1=mix(after[0],after[1],t);
    for(let y=Math.ceil(y0);y<y1;y++) {
      const f=(y-y0)/(y1-y0), [ya,yb,la,lb,ra,rb]=before.map((v,i)=>mix(v,after[i],f));
      const edge=mix(la,lb,t),rim=Math.max(edge,mix(ra,rb,t)),span=Math.max(.1,rim-edge);
      const band=ramp(146,170,ya)*(1-ramp(282,326,ya))*ramp(0,.13,t)*(1-ramp(.86,1,t));
      for(let x=Math.floor(edge)-27;x<=Math.min(n-2,Math.ceil(Math.max(rim,ra,rb,lb,la))+3);x++) {
        const dst=4*(n*y+x),w=band*ramp(edge-27,edge-10,x);
        if(!w)continue;
        const coverage=Math.max(0,Math.min(1,rim-x+.50))*255;
        if(coverage>0){
          const inShoulder=x>edge;
          const pos=(l,r)=>{
            if(!inShoulder)return l+x-edge;
            if(r-l<2)return Math.max(0,Math.min(n-2,r-Math.min(2,rim-x)));
            const guard=Math.min(3,span*.38,(r-l)*.38);
            if(rim-x<guard)return r-(rim-x);
            return l+(x-edge)*(r-l-guard)/Math.max(.1,span-guard);
          };
          const ax=pos(la,ra),bx=pos(lb,rb);
          // When the far drawing shows air where the shoulder used to be,
          // use the remaining visible shoulder wash up to its own contour.
          let mixInk=t;
          if(inShoulder) {
            const aa=(1-t)*Math.min(1,Math.max(0,ra-la)/3);
            const bb=t*Math.min(1,Math.max(0,rb-lb)/3);
            mixInk=bb/(aa+bb||1);
          }
          const front=inShoulder?torso:a;
          // Behind the cheek, a small strip of upper chest is still covered
          // by the original chin. Sample its painted continuation from below;
          // the outside pencil is already visible and stays at its own row.
          const under=inShoulder ? 13*ramp(0,5,rb-bx)*(1-ramp(227,241,yb)) : 0;
          const alpha=mix(sample(front,ax,ya,3),sample(b,bx,yb+under,3),mixInk)||1;
          for(let k=0;k<3;k++){
            const ink=255*mix(sample(front,ax,ya,k),sample(b,bx,yb+under,k),mixInk)/alpha;
            out[dst+k]+=w*(ink-out[dst+k]);
          }
        }
        out[dst+3]+=w*(coverage-out[dst+3]);
      }
    }
  }
}

function signedBytes(encoded) {
  const raw=atob(encoded),bytes=new Int8Array(raw.length);
  for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
  return bytes;
}
export function standingEdges(n) {
  const step=3,cols=n/step+1;
  return standEdges.map(s=>{
    const bytes=signedBytes(s),grid=new Float32Array(cols*cols),full=new Float32Array(n*n);
    let pos=0;
    for(let i=0;i<bytes.length;){
      const v=bytes[i++],count=Math.abs(v)===96?1+(bytes[i++]&255):1;
      grid.fill(v/4,pos,pos+count);pos+=count;
    }
    for(let y=0;y<n;y++){
      const iy=(y/step|0)*cols,v=(y%step)/step;
      for(let x=0;x<n;x+=step){
        const i=iy+x/step,j=i+cols,lo=grid[i]+v*(grid[j]-grid[i]);
        const inc=(grid[i+1]+v*(grid[j+1]-grid[i+1])-lo)/step;
        const k=y*n+x;full[k]=lo;full[k+1]=lo+inc;full[k+2]=lo+2*inc;
      }
    }
    return full;
  });
}

// Classify the four source texels once. Most of the interior is opaque and
// most of the surrounding paper is empty; neither needs per-pixel matte math.
function coverageCells(src,n){
  const cells=new Uint8Array(n*n);
  for(let y=0;y<n-1;y++)for(let x=0;x<n-1;x++){
    const i=y*n+x,j=i*4+3,k=j+4*n,sum=src[j]+src[j+4]+src[k]+src[k+4];
    cells[i]=sum===0?0:sum===1020?2:1;
  }
  return cells;
}

function standPixels(paint,t) {
  const {a,b,step,field,classes,frame}=paint,n=frame.width,cols=n/step+1,out=frame.data,stride=4*n;
  const [ac,bc]=classes, first=!!paint.arms, ink=first?ramp(.10,.90,t):ramp(0,.19,t);
  const edges=paint.boundaries,active=ramp(0,.12,t)*(1-ramp(.88,1,t));
  for(let y=0;y<n;y++){
    const row=(y/step|0)*cols,v=y%step/step;
    for(let x=0;x<n;x+=step){
      const i=2*(row+x/step),j=i+2*cols;
      let dx=field[i]+v*(field[j]-field[i]),dy=field[i+1]+v*(field[j+1]-field[i+1]);
      const ix=(field[i+2]+v*(field[j+2]-field[i+2])-dx)/step;
      const iy=(field[i+3]+v*(field[j+3]-field[i+3])-dy)/step;
      for(let xx=x;xx<x+step;xx++,dx+=ix,dy+=iy){
        const X=Math.max(0,Math.min(n-1.001,xx-dx*t)),Y=Math.max(0,Math.min(n-1.001,y-dy*t));
        const S=Math.max(0,Math.min(n-1.001,xx+dx*(1-t))),T=Math.max(0,Math.min(n-1.001,y+dy*(1-t)));
        const ia=(Y|0)*n+(X|0),ib=(T|0)*n+(S|0),ca=ac[ia],cb=bc[ib],o=4*(y*n+xx);
        if((!ca&&!cb)||(!first&&ink===1&&!cb)){out[o+3]=0;continue;}
        const ai=ia*4,bi=ib*4,al=ai+stride,bl=bi+stride;
        const l=X-(X|0),m=Y-(Y|0),r=S-(S|0),s=T-(T|0);
        let a0=(1-l)*(1-m),a1=l*(1-m),a2=(1-l)*m,a3=l*m;
        let b0=(1-r)*(1-s),b1=r*(1-s),b2=(1-r)*s,b3=r*s;
        let mix=ink;
        // Both exposures carry one registered set of eyes and one nose.
        if(first && t>.38 && t<.62 && Y>168 && Y<250 &&
          ((X-104)**2+(Y-188)**2<205||(X-219)**2+(Y-189)**2<205||(X-162)**2+(Y-230)**2<205))
          mix=Number(t>=.50);
        let alpha=255,scale=1;
        if(ca!==2||cb!==2){
          const aa=ca===2?255:ca===0?0:a[ai+3]*a0+a[ai+7]*a1+a[al+3]*a2+a[al+7]*a3;
          const bb=cb===2?255:cb===0?0:b[bi+3]*b0+b[bi+7]*b1+b[bl+3]*b2+b[bl+7]*b3;
          const cov=aa+(bb-aa)*mix;
          if(cov<.05){out[o+3]=0;continue;}
          scale=255/cov;alpha=cov;
          if(first){
            const da=edges[0],db=edges[1];
            const ad=da[ia]*a0+da[ia+1]*a1+da[ia+n]*a2+da[ia+n+1]*a3;
            const bd=db[ib]*b0+db[ib+1]*b1+db[ib+n]*b2+db[ib+n+1]*b3;
            alpha+=(Math.max(0,Math.min(1,.5+ad+(bd-ad)*t))*255-alpha)*active;
          }
        }
        out[o+3]=alpha;
        const ka=(1-mix)*scale,kb=mix*scale;
        a0*=ka;a1*=ka;a2*=ka;a3*=ka;b0*=kb;b1*=kb;b2*=kb;b3*=kb;
        for(let ch=0;ch<3;ch++)out[o+ch]=a[ai+ch]*a0+a[ai+4+ch]*a1+a[al+ch]*a2+a[al+4+ch]*a3+
          b[bi+ch]*b0+b[bi+4+ch]*b1+b[bl+ch]*b2+b[bl+4+ch]*b3;
      }
    }
  }
}

// The five small grids contain displacements, not pictures. Interpolate the
// guide at the current clock and sample each complete painting at its anatomical
// correspondence. Feet stay registered and shared coverage keeps the ink clean.
export class RegisteredRise {
  constructor(rig,face,p,from,to) {
    const lift=rig.geometry("wash1_lift",face,p), n=rig.parts.wash1_lift[2];
    this.box=[lift.left,lift.top,lift.w,lift.h];
    this.ctx=surface(n,n);
    const read=key=>{
      const c=this.ctx;
      c.clearRect(0,0,n,n);
      if(key==="standHalf") {
        const tile=rig.motionPiece(key);
        c.drawImage(tile.canvas,tile.x,tile.y);
      } else if (key) {
        const g=rig.geometry(key,face,p);
        if(key==="stand"){g.h=rig.extra.standRegistrationHeight;g.top=-g.h;}
        c.drawImage(rig.extra.image,...rig.parts[key],(g.left-lift.left)*n/lift.w,
          (g.top-lift.top)*n/lift.h,g.w*n/lift.w,g.h*n/lift.h);
      } else {
        c.save();c.scale(n/lift.w,n/lift.h);c.translate(-lift.left,-lift.top);
        const probe=rig.probe;rig.probe=null;
        try { rig.front(c,{...p,action:"idle",breath:0,sniff:0,blink:0,ear:0,tilt:0}); }
        finally { rig.probe=probe;c.restore(); }
      }
      return premultiply(c.getImageData(0,0,n,n).data);
    };
    this.from=from;this.a=read(from);this.b=read(to);
    if(from===null && to==="standHalf"){
      this.cheek=cheekRows(rig,face,p,this.box,n,this.a,this.b);
      this.arms=risingPaws(this.b,n);
    }
    if(to==="standHalf"||to==="stand")this.classes=[coverageCells(this.a,n),coverageCells(this.b,n)];
    if(this.arms)this.boundaries=rig.standBoundaries??=standingEdges(n);
    else if(from!=="standHalf")this.boundaries=[silhouette(this.a,n),silhouette(this.b,n)];
    this.frame=this.ctx.createImageData(n,n);
    const [step,gain,encoded]=riseGuides[from||"idle"];
    this.step=step;this.gain=gain;
    this.grids=encoded.map(signedBytes);
    this.field=new Float32Array(this.grids[0].length);
  }
  draw(c,t,probe) {
    if(this.last!==t) {
      const at=t*(this.grids.length-1), index=Math.min(this.grids.length-2,at|0), u=at-index;
      const lo=this.grids[index],hi=this.grids[index+1],field=this.field;
      for(let i=0;i<field.length;i++)field[i]=(lo[i]+(hi[i]-lo[i])*u)/this.gain;
      this.render(t);
      if(this.cheek)resolveCheek(this.cheek,this.a,this.b,this.frame.data,this.frame.width,t);
      this.ctx.putImageData(this.frame,0,0);
      if(this.arms)this.drawArms(t);
      this.last=t;
    }
    print(c,this.box,this.ctx,this.frame,probe);
  }
  drawArms(t) {
    const c=this.ctx;
    for(const [i,arm] of this.arms.entries()){
      const u=ramp(.018*i,1,t), remaining=1-u;
      const [rx,ry]=arm.root,[fx,fy]=arm.foot;
      c.save();c.globalAlpha=ramp(0,.31,t);
      c.translate(rx+(fx-rx)*remaining,ry+(fy-ry)*remaining);
      c.rotate(arm.angle*remaining);
      c.scale(1-.17*remaining,1-.46*remaining);
      c.drawImage(arm.canvas,arm.x-rx,arm.y-ry);
      c.restore();
    }
  }
  render(t) {
    if(this.classes)return standPixels(this,t);
    const n=this.frame.width, step=this.step, cols=n/step+1, field=this.field;
    // During a roll the open eye replaces a shut eye and a forefoot covers the
    // belly. Hand off those occlusions on one registered exposure.
    const a=this.a,b=this.b,out=this.frame.data,ink=ramp(.39,.61,t);
    const retiring=ramp(.38,.53,t),emerging=ramp(.47,.62,t),features=expressions[this.from];
    for(let y=0;y<n;y++) {
      const row=(y/step|0)*cols, v=y%step/step;
      for(let x=0;x<n;x+=step){
        const i=2*(row+x/step),j=i+2*cols;
        let dx=field[i]+v*(field[j]-field[i]),dy=field[i+1]+v*(field[j+1]-field[i+1]);
        const du=(field[i+2]+v*(field[j+2]-field[i+2])-dx)/step;
        const dv=(field[i+3]+v*(field[j+3]-field[i+3])-dy)/step;
        for(let col=x;col<x+step;col++,dx+=du,dy+=dv){
          const X=Math.max(0,Math.min(n-1.001,col-dx*t)),Y=Math.max(0,Math.min(n-1.001,y-dy*t));
          const S=Math.max(0,Math.min(n-1.001,col+dx*(1-t))),T=Math.max(0,Math.min(n-1.001,y+dy*(1-t)));
          const ax=X|0,ay=Y|0,bx=S|0,by=T|0, l=X-ax,m=Y-ay,r=S-bx,s=T-by;
          const ai=4*(n*ay+ax),bi=4*(n*by+bx),al=ai+4*n,bl=bi+4*n,o=4*(y*n+col);
          const a0=(1-l)*(1-m),a1=l*(1-m),a2=(1-l)*m,a3=l*m;
          const b0=(1-r)*(1-s),b1=r*(1-s),b2=(1-r)*s,b3=r*s;
          const alphaA=a[ai+3]*a0+a[ai+7]*a1+a[al+3]*a2+a[al+7]*a3;
          const alphaB=b[bi+3]*b0+b[bi+7]*b1+b[bl+3]*b2+b[bl+7]*b3;
          if(alphaA+alphaB<.1){out[o+3]=0;continue;}
          let pigment=ink,alpha=alphaA+(alphaB-alphaA)*ink;
          if(this.boundaries){
            if(alphaA<254 || alphaB<254){
              const [da,db]=this.boundaries, ia=ai/4,ib=bi/4;
              const ad=da[ia]*a0+da[ia+1]*a1+da[ia+n]*a2+da[ia+n+1]*a3;
              const bd=db[ib]*b0+db[ib+1]*b1+db[ib+n]*b2+db[ib+n+1]*b3;
              const edge=Math.max(0,Math.min(1,.5+ad+(bd-ad)*t))*255;
              const active=ramp(0,.12,t)*(1-ramp(.88,1,t));
              alpha+=(edge-alpha)*active;
            } else {
              const greenA=a[ai+1]*a0+a[ai+5]*a1+a[al+1]*a2+a[al+5]*a3;
              const greenB=b[bi+1]*b0+b[bi+5]*b1+b[bl+1]*b2+b[bl+5]*b3;
              // Closed lids, belly markings and exposed paws change which ink
              // is visible. Retire an unmatched line before developing the next.
              const diff=greenB-greenA, contrast=ramp(12,36,Math.abs(diff))*(1-ramp(111,153,Math.min(greenA,greenB)));
              pigment+=((diff>0?retiring:emerging)-pigment)*contrast;
              if(t>.38 && t<.62 && Math.abs(Y-features[1])<100){
                const near=Math.min((X-features[0])**2+(Y-features[1])**2,
                  (X-features[2])**2+(Y-features[3])**2,(X-features[4])**2+(Y-features[5])**2);
                pigment+=(Number(t>=.5)-pigment)*(1-ramp(145,250,near));
              }
            }
          }
          out[o+3]=alpha;
          const coverage=alphaA+(alphaB-alphaA)*pigment;
          if(coverage<.1){pigment=alphaA>alphaB?0:1;}
          const straight=255/(alphaA*(1-pigment)+alphaB*pigment||255);
          for(let ch=0;ch<3;ch++)out[o+ch]=straight*((a[ai+ch]*a0+a[ai+4+ch]*a1+a[al+ch]*a2+a[al+4+ch]*a3)*(1-pigment)+
            (b[bi+ch]*b0+b[bi+4+ch]*b1+b[bl+ch]*b2+b[bl+4+ch]*b3)*pigment);
        }
      }
    }
  }
}

